def slugify(name):
 import unicodedata,re
 s=name.replace('İ','i').casefold().replace('ı','i').replace('ğ','g').replace('ü','u').replace('ş','s').replace('ö','o').replace('ç','c').replace('&','-');return re.sub('-+','-',re.sub('[^a-z0-9]+','-',s)).strip('-')
