 slug=slugify(name);v=dict(name=name,slug=slug,albumId=id,albumSlug=albumslug,albumTitle=albumtitle,date=date,cover=base if id in (a1,a2) else portrait,position=position,credits=credits or 'Manifest · Hypers Music',duration=duration,url=source,description=description or f'{name}, Manifest’in {albumtitle} yayınına ait kayıttır. Resmî dinleme bağlantısı ve sanatçı künyesi Apple Music üzerinden doğrulanmıştır.',videoId={'Amatör':'JzH6uWBtC3I','Daha İyi':'vso1LpaQRbo','Toz Pembe':'0pg0raFMNIU'}.get(name),videoSource=('https://www.youtube.com/watch?v='+{'Amatör':'JzH6uWBtC3I','Daha İyi':'vso1LpaQRbo','Toz Pembe':'0pg0raFMNIU'}[name] if name in {'Amatör','Daha İyi','Toz Pembe'} else ''))
 ops.append(dict(type='song',slug=slug,expectedRevision=revision('artist_songs',slug),status='published',values=v))
