 id=a1 if i<=11 else a2;albumslug='manifestival' if i<=11 else 'manifestival-deluxe';albumtitle='manifestival' if i<=11 else 'manifestival (deluxe)';date='2025-06-13' if i<=11 else '2025-09-05';desc='Manifest’in 2025 tarihli yayını. '+('Çıtır Kızlar’ın Yaşanacaksa Yaşanacak eserine dayanan bir yorumdur.' if name=='Yaşanacaksa' else 'Deluxe sürümde yer alan ayrı düzenlemedir.' if i>11 else 'Albümün özgün parça sıralamasında yer alır.');song(name,date,id,albumslug,albumtitle,deluxe if i>11 else original,i,duration,'Manifest ve Pango' if name.startswith('Zehir') and i<=11 else 'Manifest, Arem Ozguc ve Arman Aydin' if name=='Manifest' else '',desc)
